// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// runOnceForEachItem : $json = current row from Sheets
const row = $json;

// Parse JSON fields stored as strings in Sheets
let objectives = [];
try { objectives = JSON.parse(row.objectives || '[]'); } catch(e) {}
let prerequisites = [];
try { prerequisites = JSON.parse(row.prerequisites || '[]'); } catch(e) {}
let outline = [];
try { outline = JSON.parse(row.outline || '[]'); } catch(e) {}

const durationStr = String(row.Duree || '10h');
const durationHours = parseInt((durationStr.match(/^(\d+)/) || ['10','10'])[1]);

return {
  json: {
    id: row.id,
    title: row.Titre || '',
    level: (row.Niveau || 'debutant').toLowerCase().trim(),
    target_audience: row.Audience || 'Entrepreneurs et professionnels du digital en Afrique francophone',
    learning_objectives: objectives.length ? objectives : [row.Besoin_Local || ''],
    prerequisites: prerequisites,
    duration_hours: durationHours,
    outline_preview: outline.length ? outline : [],
    category: row.category || 'Marketing Digital',
    price_range: row.price_range || '',
    besoin_local: row.Besoin_Local || ''
  }
};

// runOnceForEachItem
const input = $input.item.json;
const allBuild = $('Build — Payload cours (par ligne)').all();
const buildData = allBuild[$itemIndex]?.json || {};

// 1. Extract raw text
let rawText = '';
let curriculum = null;

if (input.course && input.modules) {
  curriculum = input;
} else if (input.content?.parts) {
  rawText = input.content.parts.map(p => p.text || '').join('');
} else if (typeof input === 'string') {
  rawText = input;
} else {
  rawText = JSON.stringify(input);
}

// 2. Parse with multiple strategies
if (!curriculum && rawText) {
  let cleaned = rawText.trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();
  cleaned = cleaned.replace(/,\s*([\}\]])/g, '$1');
  cleaned = cleaned.replace(/\r\n/g, '\n');

  // Strategy 1: direct parse
  try { curriculum = JSON.parse(cleaned); } catch(e1) {}

  // Strategy 2: fix newlines inside strings
  if (!curriculum) {
    let fixed = '';
    let inStr = false, esc = false;
    for (let i = 0; i < cleaned.length; i++) {
      const c = cleaned[i];
      if (esc) { fixed += c; esc = false; continue; }
      if (c === '\\') { fixed += c; esc = true; continue; }
      if (c === '"') { fixed += c; inStr = !inStr; continue; }
      if (inStr && c === '\n') { fixed += '\\n'; continue; }
      if (inStr && c === '\t') { fixed += '\\t'; continue; }
      fixed += c;
    }
    fixed = fixed.replace(/,\s*([\}\]])/g, '$1');
    try { curriculum = JSON.parse(fixed); } catch(e2) {
      // Strategy 3: regex block
      const match = fixed.match(/\{[\s\S]+\}/);
      if (match) {
        let block = match[0].replace(/,\s*([\}\]])/g, '$1');
        try { curriculum = JSON.parse(block); } catch(e3) {}
      }
    }
  }

  // Strategy 4: TRUNCATED JSON RECOVERY
  // If Gemini response was cut off, try to close all open brackets/braces
  if (!curriculum) {
    let attempt = cleaned;
    // Remove trailing incomplete string (ends mid-value)
    attempt = attempt.replace(/,?\s*"[^"]*$/, '');
    // Count open brackets
    let opens = 0, closes = 0, openSq = 0, closeSq = 0;
    let inS = false, es = false;
    for (const c of attempt) {
      if (es) { es = false; continue; }
      if (c === '\\') { es = true; continue; }
      if (c === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (c === '{') opens++;
      if (c === '}') closes++;
      if (c === '[') openSq++;
      if (c === ']') closeSq++;
    }
    // Close missing brackets
    const missingBraces = opens - closes;
    const missingSq = openSq - closeSq;
    if (missingBraces > 0 || missingSq > 0) {
      attempt += ']'.repeat(Math.max(0, missingSq)) + '}'.repeat(Math.max(0, missingBraces));
      attempt = attempt.replace(/,\s*([\}\]])/g, '$1');
      try { curriculum = JSON.parse(attempt); } catch(e4) {}
    }
  }
}

// 3. Graceful fallback
if (!curriculum || (!curriculum.course && !curriculum.modules)) {
  return {
    json: {
      curriculum: { course: { title: buildData.title || '?' }, modules: [] },
      sheet_rows: [],
      course_title: buildData.title || '?',
      total_modules: 0,
      total_lessons: 0,
      original_duration: (buildData.duration_hours || 10) + 'h',
      id: buildData.id,
      _parse_failed: true,
      _error: 'Parse failed. Text length: ' + rawText.length
    }
  };
}

// 4. Build sheet rows
const course = curriculum.course || {};
const modules = curriculum.modules || [];
const originalDuration = buildData.duration_hours || 10;

const sheetRows = [];
for (const mod of modules) {
  for (const lesson of (mod.lessons || [])) {
    sheetRows.push({
      Cours: course.title,
      Module: 'M' + mod.module_number + ': ' + mod.title,
      Lecon: 'L' + lesson.lesson_number + ': ' + lesson.title,
      Type: lesson.type || 'text',
      Duree: (lesson.duration_minutes || 4) + ' min',
      Status_Contenu: 'a_produire',
      Status_Quiz: mod.module_quiz ? 'a_produire' : 'n/a',
      Status_Media: (lesson.media_needed && lesson.media_needed.type) ? 'a_produire' : 'n/a',
      Status_Publication: 'en_conception'
    });
  }
  if (mod.module_quiz) {
    sheetRows.push({
      Cours: course.title,
      Module: 'M' + mod.module_number + ': ' + mod.title,
      Lecon: 'Quiz: ' + (mod.module_quiz.title || 'Quiz Module ' + mod.module_number),
      Type: 'quiz',
      Duree: ((mod.module_quiz.questions_count || 5) * 2) + ' min',
      Status_Contenu: 'n/a',
      Status_Quiz: 'a_produire',
      Status_Media: 'n/a',
      Status_Publication: 'en_conception'
    });
  }
  if (mod.practical_exercise) {
    sheetRows.push({
      Cours: course.title,
      Module: 'M' + mod.module_number + ': ' + mod.title,
      Lecon: 'Mission: ' + (mod.practical_exercise.title || 'Exercice Module ' + mod.module_number),
      Type: 'mission',
      Duree: (mod.practical_exercise.duration_minutes || 15) + ' min',
      Status_Contenu: 'a_produire',
      Status_Quiz: 'n/a',
      Status_Media: 'n/a',
      Status_Publication: 'en_conception'
    });
  }
}

return {
  json: {
    curriculum,
    sheet_rows: sheetRows,
    course_title: course.title,
    total_modules: modules.length,
    total_lessons: sheetRows.length,
    original_duration: originalDuration + 'h',
    id: buildData.id,
    _parse_failed: false
  }
};

